+    clearSearchFilters();
+    onSearchFilterChange();
+    input.focus({ preventScroll: true });
+  });
+
+  // Click-away closes the results overlay (the tools line stays as set).
+  document.addEventListener("click", (e) => {
+    if (!root.contains(e.target)) setSearchOpen(false);
+  });
 }

