+
+function setActiveRow(i) {
+  const rows = [...$("ssResults").querySelectorAll(".ss-row")];
+  searchUi.active = i;
+  rows.forEach((row, j) => {
+    row.classList.toggle("is-active", j === i);
+    row.setAttribute("aria-selected", String(j === i));
+  });
