+    },
+  },
+  {
+    key: "price",
+    id: "Price",
+    multi: false,
+    any: "Any price",
+    money: true,
+    values: () => ["free", "10", "15", "20", "30"],
+    label: (v) => (v === "free" ? "Free" : `Up to £${v}`),
+    matches: (show, v) =>
