// One reusable driver for the planner. Re-point it, don't rewrite it.
//   node drive.mjs <out.png> [--window d0:d1] [--dismiss sleep|travel] [--reload] [--clip selector]
import { chromium } from '/opt/node22/lib/node_modules/playwright/index.mjs';

const [out, ...flags] = process.argv.slice(2);
const flag = (name, dflt = null) => {
  const i = flags.indexOf(`--${name}`);
  return i === -1 ? dflt : (flags[i + 1] ?? true);
};
const FAVS = '/tmp/claude-0/-home-user-EdFringeNow/45fa8e89-dffb-5987-8e32-a2aa1c3e3f37/scratchpad/favs.txt';

const [vw, vh] = String(flag('viewport', '1440x1000')).split('x').map(Number);
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: vw, height: vh } });
const errors = [];
page.on('console', (m) => {
  const t = m.text();
  // Known-noisy from python -m http.server: no favicon ships, and the browser
  // logs a connection reset as it tears down.
  if (m.type() === 'error' && !/favicon\.ico|ERR_CONNECTION_RESET/.test(t)) errors.push(t);
});
page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`));

await page.goto('http://localhost:8000/plan/', { waitUntil: 'networkidle' });
await page.setInputFiles('#csvInput', FAVS);
await page.waitForSelector('.sch-day', { timeout: 15000 });

const dismiss = flag('dismiss');
if (dismiss) {
  await page.click(`.sch-nag[data-nag="${dismiss}"] .nag-x`);
  await page.waitForTimeout(300);
}
// Drag the "day ends" line down to the bottom of the axis: the night zone
// collapses, so its nag must vanish rather than spill (mid-drag *and* after the
// re-plan on drop).
let midDrag = null;
if (flag('dragDayEnd')) {
  const grip = page.locator('.sch-dayline--end .dl-grip');
  const box = await grip.boundingBox();
  const axis = await page.locator('.sch-overlay').boundingBox();
  await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2);
  await page.mouse.down();
  await page.mouse.move(box.x + box.width / 2, axis.y + axis.height - 2, { steps: 10 });
  midDrag = await page.evaluate(() => {
    const n = document.querySelector('.sch-zone .sch-nag');
    return { present: !!n, hidden: n ? n.hidden : null, zoneH: document.querySelectorAll('.sch-zone')[1]?.getBoundingClientRect().height };
  });
  await page.mouse.up();
  await page.waitForTimeout(400);
}

if (flag('reload')) {
  await page.reload({ waitUntil: 'networkidle' });
  await page.waitForSelector('.sch-day', { timeout: 15000 });
}

const report = await page.evaluate(() => {
  const nags = [...document.querySelectorAll('.sch-nag')].map((n) => {
    const a = n.querySelector('.nag-cta');
    const region = n.closest('.sch-zone') ? 'night-zone' : n.closest('.sch-trip')?.dataset.trip || '?';
    const r = n.getBoundingClientRect();
    const pr = n.parentElement.getBoundingClientRect();
    return {
      kind: n.dataset.nag, region, text: a.textContent.trim(), href: a.href,
      rel: a.rel, target: a.target,
      insideRegion: r.top >= pr.top - 1 && r.bottom <= pr.bottom + 1,
      xLabel: n.querySelector('.nag-x')?.getAttribute('aria-label'),
      visible: r.width > 0 && r.height > 0,
    };
  });
  return { nags, stored: localStorage.getItem('edfringe.plan.nags.v1'), cols: document.getElementById('schedule').className };
});
if (midDrag) report.midDrag = midDrag;

await page.locator(flag('clip', '#scheduleWrap')).screenshot({ path: out });
await browser.close();
console.log(JSON.stringify(report, null, 2));
if (errors.length) { console.error('CONSOLE ERRORS:', errors); process.exit(1); }

